def get_timing_signal_1d(length, channels, min_timescale=1.0, max_timescale=1.0e4, start_index=0):
    # Create a tensor of positions
    position = torch.arange(length, dtype=torch.float32) + start_index
    # Two Component, Sin and Cosine
    num_timescales = channels // 2
    log_timescale_increment = (math.log(float(max_timescale) / float(min_timescale)) / max(num_timescales - 1, 1))
    inv_timescales = min_timescale * torch.exp(
        torch.arange(num_timescales, dtype=torch.float32) * -log_timescale_increment)
    # [length, num_timescales] we want to use broadcast, you have different dimensions of two tensors make it as a matrix for element-wise operation
    scaled_time = position.unsqueeze(1) * inv_timescales.unsqueeze(0)
    # Generate the sinusoidal signals
    signal = torch.cat([torch.sin(scaled_time), torch.cos(scaled_time)], dim=1)
    # Pad the signal if channels is odd
    if channels % 2 != 0:
        signal = torch.nn.functional.pad(signal, (0, 1))
    # Reshape the signal to match the required shape [1, length, channels], should be the same as the output of word embedding
    signal = signal.view(1, length, channels)
    return signal


