def add_timing_signal_1d(x, min_timescale=1.0, max_timescale=1.0e4, start_index=0):
    length = shape_list(x)[1]
    channels = shape_list(x)[2]
    signal = get_timing_signal_1d(length, channels, min_timescale, max_timescale, start_index)
    return x + signal


def add_timing_signal_nd(x, min_timescale=1.0, max_timescale=1.0e4):
    # Batch Dimension: The first dimension corresponds to the batch size.
    # Channel Dimension: The last dimension corresponds to the feature channels.
    num_dims = len(x.shape) - 2
    channels = x.shape[-1]
    # Total Number of Timescales// Number of Sinusoids per Dimensio
    num_timescales = channels // (num_dims * 2)
    log_timescale_increment = math.log(float(max_timescale) / float(min_timescale)) / max(num_timescales - 1, 1)
    inv_timescales = min_timescale * torch.exp(torch.arange(num_timescales).float() * -log_timescale_increment)

    for dim in range(num_dims):
        length = x.shape[dim + 1]
        position = torch.arange(length).float()
        scaled_time = position.unsqueeze(1) * inv_timescales.unsqueeze(0)
        signal = torch.cat([torch.sin(scaled_time), torch.cos(scaled_time)], dim=1)
        # amount of padding needed to align the positional encoding signal with the input tensor's channels dimension.
        # padding required to ensure correct length (prepad for second dim, post pad for first dim so they have length 16)
        prepad = dim * 2 * num_timescales
        postpad = channels - (dim + 1) * 2 * num_timescales
        signal = torch.nn.functional.pad(signal, (prepad, postpad))
        # broadcast
        for i in range(1 + dim):
            signal = signal.unsqueeze(0)
        for i in range(num_dims - 1 - dim):
            signal = signal.unsqueeze(-2)
        x = x + signal
    return x


