"""## Mini_handson Transfomer Structure (Keras for students not familiar with pytorch)"""

from tensorflow.keras.layers import Embedding, Dropout, MultiHeadAttention, LayerNormalization, Dense

"""### Sinusoidal, Revisit"""

import tensorflow as tf


# compute frequencies for all
def get_angles(pos, k, d):
    i = k // 2
    angles = pos / np.power(10000, 2 * i / d)
    return angles


def positional_encoding(positions, d):
    """
    Arguments:
        positions (int) -- Maximum number of positions to be encoded
        d (int) -- Encoding size
    """
    pos_m = np.arange(positions)[:, np.newaxis]
    angle_rads = get_angles(pos_m, np.arange(d)[np.newaxis, :], d)
    angle_rads[:, 0::2] = np.sin(angle_rads[:, 0::2])
    angle_rads[:, 1::2] = np.cos(angle_rads[:, 1::2])
    pos_encoding = angle_rads[np.newaxis, ...]

    return tf.cast(pos_encoding, dtype=tf.float32)


"""### Padding Mask

When processing sequence data, it is very common for individual samples to have different lengths. Consider the following example (text tokenized as words):

    [["Do", "you", "know", "when", "Jane", "is", "going", "to", "visit", "Africa"],
     ["Jane", "visits", "Africa", "in", "September" ],
     ["Exciting", "!"]
    ]

which might get vectorized as:

    [[ 71, 121, 4, 56, 99, 2344, 345, 1284, 15],
     [ 56, 1285, 15, 181, 545],
     [ 87, 600]
    ]

When passing sequences into a transformer model, it is important (positional encoding, parallel processing ..) that they are of uniform length. You can achieve this by padding the sequence with zeros, and truncating sentences that exceed the maximum length of your model:

    [[ 71, 121, 4, 56, 99],
     [ 2344, 345, 1284, 15, 0],
     [ 56, 1285, 15, 181, 545],
     [ 87, 600, 0, 0, 0],
    ]

Sequences longer than the maximum length of five will be truncated, and zeros will be added to the truncated sequence to achieve uniform length. Similarly, for sequences shorter than the maximum length, zeros will also be added for padding. However, these zeros will affect the softmax calculation - this is when a padding mask comes in handy! You will need to define a boolean mask that specifies to which elements you must attend(1) and which elements you must ignore(0). Later you will use that mask to set all the zeros in the sequence to a value close to negative infinity (-1e9),so that when you take the softmax, the zeros don't affect the score.
"""

raw_inputs = [
    [711, 632, 71],
    [73, 8, 3215, 55, 927],
    [83, 91, 1, 645, 1253, 927],
]

# tf.keras pad sequence, the padding will follow the longest sequence
padded_inputs = tf.keras.preprocessing.sequence.pad_sequences(raw_inputs, padding="post")
print("Padded Inputs Shape:", padded_inputs.shape)


# boolean if it is pad make it zero (where 1 -  comes from)
def create_padding_mask(decoder_token_ids):
    seq = 1 - tf.cast(tf.math.equal(decoder_token_ids, 0), tf.float32)
    seq = seq[:, np.newaxis]
    #  [batch_size, 1, 1, seq_len] for future caculation
    return seq[:, np.newaxis, :]


x = create_padding_mask(padded_inputs)
print("Padding Mask Shape:", x.shape)
print(x)

# Calculate the final output using softmax
mask = 1 - create_padding_mask(padded_inputs)
large_negative_value = -1.0e9
final_output = tf.keras.activations.softmax(x + mask * large_negative_value)
print("Final Output Shape:", final_output.shape)
print("Final Output:", final_output)

"""The look-ahead mask follows similar intuition. In training, you will have access to the complete correct output of your training example. The look-ahead mask helps your model pretend that it correctly predicted a part of the output and see if, *without looking ahead*, it can correctly predict the next output.

For example, if the expected correct output is `[1, 2, 3]` and you wanted to see if given that the model correctly predicted the first value it could predict the second value, you would mask out the second and third values. So you would input the masked sequence `[1, -1e9, -1e9]` and see if it could generate `[1, 2, -1e9]`.

### Decoder Masks
"""


def create_look_ahead_mask(sequence_length):
    # The resulting tensor will have the same shape as the input tensor, but with all elements above the main diagonal set to zero.
    mask = tf.linalg.band_part(tf.ones((1, sequence_length, sequence_length)), -1, 0)
    return mask


"""### Self-Attention

**This is very important,** the leading dimensions typically refer to the batch_size and the num_heads, all three tensors, Q, K, and V, must have the same batch_size and num_heads. This ensures that within each batch and for each attention head, the computations are consistent.

![image.png](data:image/png;base64,)

For K and V, the sequence lengths must match (seq_len_k = seq_len_v). This is because K and V are derived from the same input sequence, representing the same set of elements in the sequence.

The sequence length of the query (seq_len_q) can differ from that of K and V (seq_len_k or seq_len_v). This flexibility allows the model to query different lengths of sequences, enabling operations like cross-attention where the query comes from a different sequence than the key and value.
"""


def scaled_dot_product_attention(q, k, v, mask):
    """
    Calculate the attention weights.
      q, k, v must have matching leading dimensions.
      k, v must have matching penultimate dimension, i.e.: seq_len_k = seq_len_v.
      The mask has different shapes depending on its type(padding or look ahead)
      but it must be broadcastable for addition.

    Arguments:
        q -- query shape == (..., seq_len_q, depth)
        k -- key shape == (..., seq_len_k, depth)
        v -- value shape == (..., seq_len_v, depth_v)
        mask: Float tensor with shape broadcastable
              to (..., seq_len_q, seq_len_k). Defaults to None.

    Returns:
        output -- attention_weights
    """
    matmul_qk = tf.matmul(q, k.T)
    dk = np.sqrt(k.shape[-1])
    scaled_attention_logits = matmul_qk / dk
    if mask is not None:
        scaled_attention_logits += (1 - mask) * -1e9
    attention_weights = tf.keras.activations.softmax(scaled_attention_logits)  # (..., seq_len_q, seq_len_k)
    output = tf.matmul(attention_weights, v)  # (..., seq_len_q, depth_v)
    return output, attention_weights


"""<a name='4'></a>
## Encoder Layer

The Transformer Encoder layer pairs self-attention and convolutional neural network style of processing to improve the speed of training and passes K and V matrices to the Decoder, which you'll build later in the assignment. In this section of the assignment, you will implement the Encoder by pairing multi-head attention and a feed forward neural network

![image.png](data:image/png;base64,)

* `MultiHeadAttention` you can think of as computing the self-attention several times to detect different features.
* Feed forward neural network contains two Dense layers which we'll implement as the function `FullyConnected`

Your input sentence first passes through a *multi-head attention layer*, where the encoder looks at other words in the input sentence as it encodes a specific word. The outputs of the multi-head attention layer are then fed to a *feed forward neural network*. The exact same feed forward network is independently applied to each position.

* For the `MultiHeadAttention` layer, we will use the [Keras implementation](https://www.tensorflow.org/api_docs/python/tf/keras/layers/MultiHeadAttention). If you're curious about how to split the query matrix Q, key matrix K, and value matrix V into different heads, you can look through the implementation.
* We will also use the [Sequential API](https://keras.io/api/models/sequential/) with two dense layers to built the feed forward neural network layers.
"""


# FFN, two linearlayers one with relu (broad cast to alleviate effects of losses due to relu while introduce non linearity)
def FullyConnected(embedding_dim, fully_connected_dim):
    return tf.keras.Sequential([
        tf.keras.layers.Dense(fully_connected_dim, activation='relu'),  # (batch_size, seq_len, dff)
        tf.keras.layers.Dense(embedding_dim)  # (batch_size, seq_len, embedding_dim)
    ])


